UPDATE `servicios` SET `descripcion` = 'Asesoría y Guía en Crianza Waldorf\n\nCiclo de 5 sesiones online de 1 hora cada una, 1 vez por semana.\n\nConoceremos las necesidades de los niños y niñas del primer septenio (0 a 7 años).\n\nSesión 1: Anamnesis\nSesión 2: Crianza Waldorf y los Septenios\nSesión 3: Vínculo y Apego\nSesión 4: Imitación, Ritmo y Límites\nSesión 5: Juego y Movimiento libre' WHERE `nombre` = 'Guía en Crianza' LIMIT 1;
